CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role='super_admin'), UNIQUE(user_id,role), UNIQUE(role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_self ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,text) TO authenticated,service_role;
CREATE TABLE public.account_bans (user_id uuid PRIMARY KEY, reason text NOT NULL, banned_at timestamptz NOT NULL DEFAULT now(), banned_by uuid NOT NULL, expires_at timestamptz, revoked_at timestamptz, revoked_by uuid);
GRANT SELECT ON public.account_bans TO authenticated;
GRANT ALL ON public.account_bans TO service_role;
ALTER TABLE public.account_bans ENABLE ROW LEVEL SECURITY;
CREATE POLICY bans_read_self ON public.account_bans FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_account_banned(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.account_bans WHERE user_id=_user_id AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at>now())) $$;
REVOKE ALL ON FUNCTION public.is_account_banned(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_account_banned(uuid) TO authenticated,service_role;
CREATE TABLE public.admin_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_id uuid NOT NULL, action text NOT NULL, target_id uuid, target_label text, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.admin_audit_logs TO service_role;
ALTER TABLE public.admin_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE INDEX admin_audit_time ON public.admin_audit_logs(created_at DESC);
CREATE TABLE public.admin_login_limits (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now(), locked_until timestamptz);
GRANT ALL ON public.admin_login_limits TO service_role;
ALTER TABLE public.admin_login_limits ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_storage_cleanup (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), last_error text);
GRANT ALL ON public.admin_storage_cleanup TO service_role;
ALTER TABLE public.admin_storage_cleanup ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chats ADD COLUMN is_verified boolean NOT NULL DEFAULT false;
CREATE FUNCTION public.admin_login_attempt(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r public.admin_login_limits; BEGIN INSERT INTO public.admin_login_limits(key) VALUES(_key) ON CONFLICT DO NOTHING; SELECT * INTO r FROM public.admin_login_limits WHERE key=_key FOR UPDATE; IF r.locked_until>now() THEN RETURN false; END IF; IF r.window_start<now()-interval '15 minutes' THEN r.attempts:=0; r.window_start:=now(); END IF; IF r.attempts>=5 THEN UPDATE public.admin_login_limits SET locked_until=now()+interval '15 minutes' WHERE key=_key; RETURN false; END IF; UPDATE public.admin_login_limits SET attempts=r.attempts+1,window_start=r.window_start,locked_until=NULL WHERE key=_key; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.admin_login_attempt(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_login_attempt(text) TO service_role;
CREATE FUNCTION public.guard_xgram_moderation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF COALESCE(auth.role(),'')='service_role' THEN RETURN COALESCE(NEW,OLD); END IF; IF public.is_account_banned(auth.uid()) THEN RAISE EXCEPTION 'Account banned' USING ERRCODE='42501'; END IF; IF TG_TABLE_NAME IN ('profiles','chats') THEN IF TG_OP='INSERT' AND NEW.is_verified THEN RAISE EXCEPTION 'Verification requires Super Admin' USING ERRCODE='42501'; ELSIF TG_OP='UPDATE' AND NEW.is_verified IS DISTINCT FROM OLD.is_verified THEN RAISE EXCEPTION 'Verification requires Super Admin' USING ERRCODE='42501'; END IF; END IF; RETURN COALESCE(NEW,OLD); END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','chats','messages','chat_members','calls','message_reactions','message_reads'] LOOP EXECUTE format('CREATE TRIGGER guard_xgram_moderation BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_xgram_moderation()',t); IF t<>'profiles' THEN EXECUTE format('CREATE POLICY ban_restrict_access ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (NOT public.is_account_banned(auth.uid())) WITH CHECK (NOT public.is_account_banned(auth.uid()))',t); END IF; END LOOP; END $$;
CREATE POLICY ban_restrict_storage ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING (bucket_id<>'xgram-media' OR NOT public.is_account_banned(auth.uid())) WITH CHECK (bucket_id<>'xgram-media' OR NOT public.is_account_banned(auth.uid()));
CREATE OR REPLACE FUNCTION public.is_chat_member(_chat_id uuid,_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT NOT public.is_account_banned(_user_id) AND EXISTS(SELECT 1 FROM public.chat_members WHERE chat_id=_chat_id AND user_id=_user_id) $$;
CREATE OR REPLACE FUNCTION public.is_chat_admin(_chat_id uuid,_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT NOT public.is_account_banned(_user_id) AND EXISTS(SELECT 1 FROM public.chat_members WHERE chat_id=_chat_id AND user_id=_user_id AND role IN ('owner','admin')) $$;
CREATE FUNCTION public.admin_apply_action(_actor uuid,_action text,_target uuid,_reason text DEFAULT NULL,_expires timestamptz DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE label text; typ text; BEGIN IF NOT public.has_role(_actor,'super_admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF _action IN ('verify_user','unverify_user','ban_user','unban_user') THEN SELECT username INTO label FROM public.profiles WHERE id=_target; IF NOT FOUND THEN RAISE EXCEPTION 'Account not found'; END IF; IF public.has_role(_target,'super_admin') AND _action IN ('ban_user','unban_user') THEN RAISE EXCEPTION 'Cannot ban the Super Admin'; END IF;
IF _action='verify_user' OR _action='unverify_user' THEN UPDATE public.profiles SET is_verified=(_action='verify_user') WHERE id=_target;
ELSIF _action='ban_user' THEN IF length(trim(COALESCE(_reason,'')))<3 THEN RAISE EXCEPTION 'A ban reason is required'; END IF; IF _expires IS NOT NULL AND _expires<=now() THEN RAISE EXCEPTION 'Expiration must be in the future'; END IF; INSERT INTO public.account_bans(user_id,reason,banned_by,expires_at) VALUES(_target,_reason,_actor,_expires) ON CONFLICT(user_id) DO UPDATE SET reason=EXCLUDED.reason,banned_by=_actor,banned_at=now(),expires_at=_expires,revoked_at=NULL,revoked_by=NULL; UPDATE public.calls SET status='ended',ended_at=now(),ended_by=_actor WHERE (caller_id=_target OR receiver_id=_target) AND status IN ('ringing','accepted','active');
ELSE UPDATE public.account_bans SET revoked_at=now(),revoked_by=_actor WHERE user_id=_target; END IF;
ELSIF _action IN ('verify_channel','unverify_channel','delete_channel','delete_group') THEN SELECT title,type INTO label,typ FROM public.chats WHERE id=_target FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Conversation not found'; END IF; IF (_action='delete_group' AND typ<>'group') OR (_action<>'delete_group' AND typ<>'channel') THEN RAISE EXCEPTION 'Invalid conversation type'; END IF; IF _action IN ('verify_channel','unverify_channel') THEN UPDATE public.chats SET is_verified=(_action='verify_channel') WHERE id=_target; ELSE INSERT INTO public.admin_storage_cleanup(path) SELECT attachment_url FROM public.messages WHERE chat_id=_target AND attachment_url IS NOT NULL AND attachment_url!~'^(https?:|data:|blob:)' ON CONFLICT(path) DO NOTHING; INSERT INTO public.admin_storage_cleanup(path) SELECT photo_url FROM public.chats WHERE id=_target AND photo_url IS NOT NULL AND photo_url!~'^(https?:|data:|blob:)' ON CONFLICT(path) DO NOTHING; DELETE FROM public.chats WHERE id=_target; END IF;
ELSE RAISE EXCEPTION 'Invalid administrative action'; END IF;
INSERT INTO public.admin_audit_logs(admin_id,action,target_id,target_label,details) VALUES(_actor,_action,_target,label,jsonb_build_object('reason',_reason,'expires_at',_expires)); END $$;
REVOKE ALL ON FUNCTION public.admin_apply_action(uuid,text,uuid,text,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_apply_action(uuid,text,uuid,text,timestamptz) TO service_role;